28	// (entire agent-id, CLI binary to probe for detection)
29	const KNOWN_AGENTS: &[(&str, &str)] = &[
30	    ("claude-code",     "claude"),
31	    ("gemini",          "gemini"),
32	    ("codex",           "codex"),
33	    ("opencode",        "opencode"),
34	    ("cursor",          "cursor"),
35	    ("copilot-cli",     "gh"),
36	    ("factoryai-droid", "droid"),
37	    ("pi",              "pi"),
38	];
