46	pub fn run(_json: bool) -> Result<()> {
47	    let cwd = env::current_dir().context("failed to get current directory")?;
48	    let cwd_str = cwd.to_string_lossy().to_string();
49	
50	    let remote = git_remote(&cwd_str)?;
51	    let name = repo_name_from_remote(&remote);
52	
53	    let (has_settings, has_branch) = entire_check(&cwd_str);
54	    if has_settings {
55	        println!("Found .entire/settings.json — respecting existing entire configuration.");
56	    } else if has_branch {
57	        println!("Found entire/checkpoints/v1 branch — entire already initialized, skipping configure.");
58	    } else {
59	        run_configure_wizard(&cwd_str)?;
60	    }
61	
62	    install_post_commit_hook(&cwd_str)?;
63	    install_claude_hook()?;
64	    install_shell_function()?;
65	
66	    let conn = db::connect()?;
67	
68	    let exists: bool = conn
69	        .query_row(
70	            "SELECT 1 FROM repositories WHERE directory = ?1",
71	            [&cwd_str],
72	            |_| Ok(true),
73	        )
74	        .unwrap_or(false);
75	
76	    if exists {
77	        println!("'{}' is already registered with gossamer.", name);
78	        return Ok(());
79	    }
80	
81	    conn.execute(
82	        "INSERT INTO repositories (directory, remote, name) VALUES (?1, ?2, ?3)",
83	        rusqlite::params![cwd_str, remote, name],
84	    )
85	    .context("failed to register repository")?;
86	
87	    println!("Initialized '{}' ({}).", name, cwd_str);
88	    Ok(())
89	}
