91	// ── Wizard ────────────────────────────────────────────────────────────────────
92	
93	fn run_configure_wizard(cwd_str: &str) -> Result<()> {
94	    println!("\n  entire setup\n");
95	
96	    // ── Step 1: agent multi-select ────────────────────────────────────────────
97	    let mut agents: Vec<AgentOption> = KNOWN_AGENTS
98	        .iter()
99	        .map(|(id, cli)| {
100	            let detected = cmd_exists(cli)
101	                || (*id == "cursor" && std::path::Path::new("/Applications/Cursor.app").exists());
102	            AgentOption { id, detected, selected: detected }
103	        })
104	        .collect();
105	
106	    agent_picker(&mut agents)?;
107	
108	    let chosen_agents: Vec<&str> = agents.iter()
109	        .filter(|a| a.selected)
110	        .map(|a| a.id)
111	        .collect();
112	
113	    // ── Step 2–4: boolean questions (default: sensible safe values) ───────────
114	    let skip_push     = !ask_yn("Auto-push sessions on git push", false)?;
115	    let telemetry     = ask_yn("Enable anonymous telemetry", false)?;
116	    let abs_hook_path = ask_yn("Absolute git hook path (for GUI clients like GitHub Desktop)", false)?;
117	
118	    // ── Step 5–7: optional string fields ─────────────────────────────────────
119	    let checkpoint_remote = ask_optional("Checkpoint remote (e.g. github:org/repo)")?;
120	    let summarize_prov    = ask_optional("Summarize provider (e.g. anthropic)")?;
121	    let summarize_model   = if summarize_prov.is_some() {
122	        ask_optional("Summarize model (e.g. claude-sonnet-4-6)")?
123	    } else {
124	        None
125	    };
126	
127	    println!();
128	
129	    // ── Build and run `entire configure` ──────────────────────────────────────
130	    let mut configure_args = vec!["configure".to_string()];
131	    if skip_push     { configure_args.push("--skip-push-sessions".to_string()); }
132	    if telemetry     { configure_args.push("--telemetry".to_string()); }
133	    if abs_hook_path { configure_args.push("--absolute-git-hook-path".to_string()); }
134	    if let Some(r) = &checkpoint_remote {
135	        configure_args.extend(["--checkpoint-remote".to_string(), r.clone()]);
136	    }
137	    if let Some(p) = &summarize_prov {
138	        configure_args.extend(["--summarize-provider".to_string(), p.clone()]);
139	    }
140	    if let Some(m) = &summarize_model {
141	        configure_args.extend(["--summarize-model".to_string(), m.clone()]);
142	    }
143	
144	    println!("Running: entire {}", configure_args.join(" "));
145	    let status = Command::new("entire")
146	        .args(&configure_args)
147	        .current_dir(cwd_str)
148	        .status()
149	        .context("`entire configure` failed to launch — is entireio installed?")?;
150	    if !status.success() {
151	        anyhow::bail!("`entire configure` exited with {}", status);
152	    }
153	
154	    // ── Run `entire agent add` for each selected agent ────────────────────────
155	    for agent in &chosen_agents {
156	        println!("Running: entire agent add {agent}");
157	        let s = Command::new("entire")
158	            .args(["agent", "add", agent])
159	            .current_dir(cwd_str)
160	            .status()
161	            .context("failed to run `entire agent add`")?;
162	        if !s.success() {
163	            eprintln!("warning: `entire agent add {agent}` exited with {s}");
164	        }
165	    }
166	
167	    Ok(())
168	}
169	
170	// ── Interactive agent picker ──────────────────────────────────────────────────
171	
172	fn agent_picker(agents: &mut Vec<AgentOption>) -> Result<()> {
173	    let mut stdout = io::stdout();
174	
175	    terminal::enable_raw_mode()?;
176	    let result = agent_picker_inner(&mut stdout, agents);
177	    terminal::disable_raw_mode()?;
178	    result
179	}
180	
181	fn agent_picker_inner(stdout: &mut impl Write, agents: &mut Vec<AgentOption>) -> Result<()> {
182	    write!(stdout, "  Agents  \x1b[38;5;240m↑↓/jk navigate  space toggle  enter confirm\x1b[0m\r\n\r\n")?;
183	    stdout.flush()?;
184	
185	    let (_, list_top) = cursor::position()?;
186	    let mut sel = 0usize;
187	
188	    draw_agent_list(stdout, agents, sel, list_top)?;
189	
190	    loop {
191	        match event::read()? {
192	            Event::Key(k) => match k.code {
193	                KeyCode::Up | KeyCode::Char('k') => {
194	                    if sel > 0 { sel -= 1; }
195	                    draw_agent_list(stdout, agents, sel, list_top)?;
196	                }
197	                KeyCode::Down | KeyCode::Char('j') => {
198	                    if sel + 1 < agents.len() { sel += 1; }
199	                    draw_agent_list(stdout, agents, sel, list_top)?;
200	                }
201	                KeyCode::Char(' ') => {
202	                    agents[sel].selected = !agents[sel].selected;
203	                    draw_agent_list(stdout, agents, sel, list_top)?;
204	                }
205	                KeyCode::Enter => break,
206	                KeyCode::Esc  => anyhow::bail!("setup aborted"),
207	                _ => {}
208	            }
209	            _ => {}
210	        }
211	    }
212	
213	    // Park the cursor below the list before returning to normal mode.
214	    execute!(stdout, cursor::MoveTo(0, list_top + agents.len() as u16))?;
215	    write!(stdout, "\r\n")?;
216	    stdout.flush()?;
217	    Ok(())
218	}
219	
220	fn draw_agent_list(stdout: &mut impl Write, agents: &[AgentOption], sel: usize, list_top: u16) -> io::Result<()> {
221	    for (i, agent) in agents.iter().enumerate() {
222	        execute!(stdout, cursor::MoveTo(0, list_top + i as u16))?;
223	        let check      = if agent.selected { "x" } else { " " };
224	        let check_col  = if agent.selected { "\x1b[38;5;82m" } else { "\x1b[38;5;240m" };
225	        let id_padded  = format!("{:<20}", agent.id);
226	        let det        = if agent.detected { "detected" } else { "" };
227	        if i == sel {
228	            write!(stdout,
229	                "\x1b[48;5;236m  [{check_col}{check}\x1b[0m\x1b[48;5;236m] {id_padded}  \x1b[38;5;240m{det}\x1b[0m\x1b[48;5;236m\x1b[K\x1b[0m"
230	            )?;
231	        } else {
232	            let id_col = if agent.selected { "\x1b[38;5;255m" } else { "\x1b[38;5;245m" };
233	            write!(stdout,
234	                "  [{check_col}{check}\x1b[0m] {id_col}{id_padded}\x1b[0m  \x1b[38;5;240m{det}\x1b[0m\x1b[K"
235	            )?;
236	        }
237	    }
238	    stdout.flush()
239	}
