241	// ── Prompt helpers ────────────────────────────────────────────────────────────
242	
243	fn ask_yn(prompt: &str, default_yes: bool) -> Result<bool> {
244	    let hint = if default_yes { "[Y/n]" } else { "[y/N]" };
245	    print!("  {prompt}? {hint} ");
246	    io::stdout().flush()?;
247	
248	    terminal::enable_raw_mode()?;
249	    let mut answer: Result<bool> = Ok(default_yes);
250	    loop {
251	        match event::read() {
252	            Err(e) => { answer = Err(e.into()); break; }
253	            Ok(Event::Key(k)) => match k.code {
254	                KeyCode::Enter                        => break,
255	                KeyCode::Char('y') | KeyCode::Char('Y') => { answer = Ok(true);  break; }
256	                KeyCode::Char('n') | KeyCode::Char('N') => { answer = Ok(false); break; }
257	                KeyCode::Esc => { answer = Err(anyhow::anyhow!("setup aborted")); break; }
258	                _ => {}
259	            }
260	            _ => {}
261	        }
262	    }
263	    terminal::disable_raw_mode()?;
264	    let val = answer?;
265	    println!("{}", if val { "yes" } else { "no" });
266	    Ok(val)
267	}
268	
269	fn ask_optional(prompt: &str) -> Result<Option<String>> {
270	    print!("  {prompt} (blank to skip): ");
271	    io::stdout().flush()?;
272	    let mut line = String::new();
273	    io::stdin().lock().read_line(&mut line)?;
274	    let s = line.trim().to_string();
275	    Ok(if s.is_empty() { None } else { Some(s) })
276	}
277	
278	fn cmd_exists(cmd: &str) -> bool {
279	    Command::new("which")
280	        .arg(cmd)
281	        .output()
282	        .map(|o| o.status.success())
283	        .unwrap_or(false)
284	}
