286	// ── Rest of init (hooks, DB registration) ────────────────────────────────────
287	
288	fn entire_check(repo_dir: &str) -> (bool, bool) {
289	    let has_settings = std::path::Path::new(repo_dir)
290	        .join(".entire")
291	        .join("settings.json")
292	        .exists();
293	
294	    let has_branch = Command::new("git")
295	        .args(["show-ref", "--verify", "--quiet", "refs/heads/entire/checkpoints/v1"])
296	        .current_dir(repo_dir)
297	        .status()
298	        .map(|s| s.success())
299	        .unwrap_or(false);
300	
301	    (has_settings, has_branch)
302	}
303	
304	fn install_post_commit_hook(repo_dir: &str) -> Result<()> {
305	    let git_dir = git_common_dir(repo_dir)?;
306	    let hook_path = git_dir.join("hooks").join("post-commit");
307	
308	    if hook_path.exists() {
309	        let content = fs::read_to_string(&hook_path)?;
310	        if content.contains(HOOK_MARKER) {
311	            println!("post-commit hook already contains gossamer indexing, skipping.");
312	            return Ok(());
313	        }
314	        let mut file = fs::OpenOptions::new().append(true).open(&hook_path)?;
315	        writeln!(file, "{}", HOOK_SNIPPET)?;
316	    } else {
317	        fs::create_dir_all(hook_path.parent().unwrap())?;
318	        fs::write(&hook_path, format!("#!/bin/sh\n{}\n", HOOK_SNIPPET))?;
319	    }
320	
321	    #[cfg(unix)]
322	    {
323	        use std::os::unix::fs::PermissionsExt;
324	        let mut perms = fs::metadata(&hook_path)?.permissions();
325	        perms.set_mode(0o755);
326	        fs::set_permissions(&hook_path, perms)?;
327	    }
328	
329	    println!("Installed post-commit hook at {}.", hook_path.display());
330	    Ok(())
331	}
332	
333	fn git_common_dir(repo_dir: &str) -> Result<PathBuf> {
334	    let out = Command::new("git")
335	        .args(["rev-parse", "--git-common-dir"])
336	        .current_dir(repo_dir)
337	        .output()
338	        .context("failed to run git")?;
339	
340	    if !out.status.success() {
341	        anyhow::bail!("could not locate .git directory");
342	    }
343	
344	    let rel = PathBuf::from(String::from_utf8(out.stdout)?.trim().to_string());
345	    Ok(if rel.is_absolute() {
346	        rel
347	    } else {
348	        PathBuf::from(repo_dir).join(rel)
349	    })
350	}
351	
352	fn git_remote(dir: &str) -> Result<String> {
353	    let out = Command::new("git")
354	        .args(["remote", "get-url", "origin"])
355	        .current_dir(dir)
356	        .output()
357	        .context("failed to run git")?;
358	
359	    if !out.status.success() {
360	        anyhow::bail!("not a git repository or no 'origin' remote is configured");
361	    }
362	
363	    Ok(String::from_utf8(out.stdout)?.trim().to_string())
364	}
365	
366	fn install_claude_hook() -> Result<()> {
367	    let settings_path = dirs::home_dir()
368	        .context("could not find home directory")?
369	        .join(".claude")
370	        .join("settings.json");
371	
372	    let mut settings: Value = if settings_path.exists() {
373	        let raw = fs::read_to_string(&settings_path)?;
374	        serde_json::from_str(&raw).unwrap_or(json!({}))
375	    } else {
376	        json!({})
377	    };
378	
379	    let hooks_obj = settings
380	        .as_object_mut()
381	        .context("settings.json is not an object")?
382	        .entry("hooks")
383	        .or_insert(json!({}))
384	        .as_object_mut()
385	        .context("hooks is not an object")?;
386	
387	    // SessionStart
388	    {
389	        let start_hooks = hooks_obj
390	            .entry("SessionStart")
391	            .or_insert(json!([]))
392	            .as_array_mut()
393	            .context("SessionStart is not an array")?;
394	
395	        let already = start_hooks.iter().any(|e| {
396	            e.get("hooks")
397	                .and_then(Value::as_array)
398	                .map_or(false, |cmds| {
399	                    cmds.iter().any(|c| {
400	                        c.get("command").and_then(Value::as_str) == Some("gossamer session-start")
401	                    })
402	                })
403	        });
404	        if !already {
405	            start_hooks.push(json!({
406	                "matcher": "",
407	                "hooks": [{ "type": "command", "command": "gossamer session-start" }]
408	            }));
409	            println!("Registered Claude Code SessionStart hook.");
410	        } else {
411	            println!("Claude Code SessionStart hook already registered, skipping.");
412	        }
413	    }
414	
415	    // Stop
416	    {
417	        let stop_hooks = hooks_obj
418	            .entry("Stop")
419	            .or_insert(json!([]))
420	            .as_array_mut()
421	            .context("Stop is not an array")?;
422	
423	        let already = stop_hooks.iter().any(|e| {
424	            e.get("hooks")
425	                .and_then(Value::as_array)
426	                .map_or(false, |cmds| {
427	                    cmds.iter().any(|c| {
428	                        c.get("command").and_then(Value::as_str)
429	                            == Some("gossamer session-stop >/dev/null 2>&1")
430	                    })
431	                })
432	        });
433	        if !already {
434	            stop_hooks.push(json!({
435	                "matcher": "",
436	                "hooks": [{ "type": "command", "command": "gossamer session-stop >/dev/null 2>&1" }]
437	            }));
438	            println!("Registered Claude Code Stop hook.");
439	        } else {
440	            println!("Claude Code Stop hook already registered, skipping.");
441	        }
442	    }
443	
444	    if let Some(parent) = settings_path.parent() {
445	        fs::create_dir_all(parent)?;
446	    }
447	    fs::write(&settings_path, serde_json::to_string_pretty(&settings)?)?;
448	    println!("Claude Code hooks saved to {}.", settings_path.display());
449	    Ok(())
450	}
451	
452	fn install_shell_function() -> Result<()> {
453	    let home = dirs::home_dir().context("could not find home directory")?;
454	
455	    let shell = std::env::var("SHELL").unwrap_or_default();
456	    let rc_path = if shell.contains("zsh") {
457	        home.join(".zshrc")
458	    } else if shell.contains("bash") {
459	        let bp = home.join(".bash_profile");
460	        if bp.exists() { bp } else { home.join(".bashrc") }
461	    } else {
462	        println!("Shell function not installed (unknown shell '{shell}'). Add manually:");
463	        println!("  gr() {{ local p; p=$(gossamer repo); [[ -n \"$p\" ]] && cd \"$p\"; }}");
464	        return Ok(());
465	    };
466	
467	    if rc_path.exists() {
468	        let content = fs::read_to_string(&rc_path)?;
469	        if content.contains(SHELL_MARKER) {
470	            println!("Shell function `gr` already in {}, skipping.", rc_path.display());
471	            return Ok(());
472	        }
473	    }
474	
475	    let mut file = fs::OpenOptions::new().create(true).append(true).open(&rc_path)?;
476	    writeln!(file, "{}", SHELL_SNIPPET)?;
477	    println!("Added `gr` shell function to {}.", rc_path.display());
478	    println!("Run `source {}` or open a new terminal to activate it.", rc_path.display());
479	    Ok(())
480	}
