43	const AGENTS: &[(&str, &str, u8)] = &[
44	    ("Claude Code", "claude", 214),
45	    ("Gemini CLI",  "gemini", 75),
46	    ("Aider",       "aider",  42),
47	];
48	
49	// ── Entry point ───────────────────────────────────────────────────────────────
50	
51	pub fn run(json: bool) -> Result<()> {
52	    let conn = db::connect()?;
53	    let repos = fetch_repos(&conn)?;
54	
55	    if json {
56	        let arr: Vec<serde_json::Value> = repos.iter().map(|r| {
57	            let worktrees: Vec<serde_json::Value> = fetch_worktrees(&r.directory).into_iter().map(|wt| serde_json::json!({
58	                "path": wt.path,
59	                "branch": wt.branch,
60	                "head": wt.head,
61	                "is_main": wt.is_main,
62	            })).collect();
63	            let sessions: Vec<serde_json::Value> = load_sessions(&r.directory).into_iter().map(|s| serde_json::json!({
64	                "session_id": s.session_id,
65	                "session_name": s.session_name,
66	                "branch": s.branch,
67	                "agent": s.agent,
68	                "updated_at": s.updated_at.to_rfc3339(),
69	                "backed_up": s.backed_up,
70	            })).collect();
71	            serde_json::json!({
72	                "name": r.name,
73	                "directory": r.directory,
74	                "remote": r.remote,
75	                "worktrees": worktrees,
76	                "sessions": sessions,
77	            })
78	        }).collect();
79	        println!("{}", serde_json::to_string_pretty(&serde_json::json!({ "repos": arr }))?);
80	        return Ok(());
81	    }
82	
83	    if repos.is_empty() {
84	        println!("No repositories tracked. Run `gossamer init` in a git repo to get started.");
85	        return Ok(());
86	    }
87	
88	    // The shell wrapper sets GOSSAMER_CDPATH to a temp file path.
89	    // We write the selected directory there instead of stdout, avoiding all
90	    // the stdout-capture / /dev/tty complexity.
91	    let cd_file = std::env::var("GOSSAMER_CDPATH").ok();
92	
93	    if !io::stdout().is_terminal() && cd_file.is_none() {
94	        // Plain list when truly non-interactive (piped, no wrapper)
95	        let cwd = env::current_dir().ok().map(|p| p.to_string_lossy().to_string());
96	        let current_dir = cwd.as_deref().and_then(|cwd| {
97	            repos.iter().find(|r| cwd.starts_with(r.directory.as_str())).map(|r| r.directory.as_str())
98	        });
99	        for repo in &repos {
100	            let is_cur = current_dir == Some(repo.directory.as_str());
101	            let dot = if is_cur { "*" } else { " " };
102	            println!("{dot} {}  {}  {}", repo.name, repo.directory, repo.remote);
103	        }
104	        return Ok(());
105	    }
106	
107	    // Register panic hook to restore terminal
108	    let orig_hook = std::panic::take_hook();
109	    std::panic::set_hook(Box::new(move |info| {
110	        let mut out = io::stdout();
111	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
112	        let _ = terminal::disable_raw_mode();
113	        orig_hook(info);
114	    }));
115	
116	    let mut stdout = io::stdout();
117	    terminal::enable_raw_mode()?;
118	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
119	
120	    let outcome = tui_loop(&mut stdout, &repos, cd_file.is_some(), None);
121	
122	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
123	    terminal::disable_raw_mode()?;
124	
125	    match outcome? {
126	        Some(TuiOutcome::CdTo(path)) => {
127	            if let Some(file) = cd_file {
128	                std::fs::write(&file, &path)?;
129	            }
130	        }
131	        Some(TuiOutcome::ResumeSession { id, cwd }) => {
132	            super::show::resume_session(&id, &cwd);
133	        }
134	        Some(TuiOutcome::LaunchAgent { cli, cwd, session_name, prompt }) => {
135	            use std::os::unix::process::CommandExt;
136	            let mut cmd = std::process::Command::new(&cli);
137	            if !cwd.is_empty() { cmd.current_dir(&cwd); }
138	            if !session_name.is_empty() { cmd.args(["-n", &session_name]); }
139	            if !prompt.is_empty() { cmd.arg(&prompt); }
140	            let err = cmd.exec();
141	            eprintln!("Failed to launch {cli}: {err}");
142	        }
143	        None => {}
144	    }
145	
146	    Ok(())
147	}
148	
149	enum TuiOutcome {
150	    CdTo(String),
151	    ResumeSession { id: String, cwd: String },
152	    LaunchAgent { cli: String, cwd: String, session_name: String, prompt: String },
153	}
154	
155	enum Screen {
156	    Repos { sel: usize },
157	    Sessions { repo_idx: usize, sel: usize, sessions: Vec<RepoSession>, worktrees: Vec<RepoWorktree> },
158	}
159	
160	fn tui_loop(stdout: &mut impl Write, repos: &[Repository], has_cd: bool, start_repo: Option<usize>) -> Result<Option<TuiOutcome>> {
161	    let cwd = env::current_dir().ok().map(|p| p.to_string_lossy().to_string());
162	    let current_repo_dir = cwd.as_deref().and_then(|cwd| {
163	        repos.iter().find(|r| cwd.starts_with(r.directory.as_str())).map(|r| r.directory.as_str())
164	    });
165	
166	    let start_sel = cwd.as_deref()
167	        .and_then(|cwd| repos.iter().position(|r| cwd.starts_with(r.directory.as_str())))
168	        .unwrap_or(0);
169	
170	    let initial = if let Some(idx) = start_repo.filter(|&i| i < repos.len()) {
171	        let sessions = load_sessions(&repos[idx].directory);
172	        let worktrees = fetch_worktrees(&repos[idx].directory);
173	        Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees }
174	    } else {
175	        Screen::Repos { sel: start_sel }
176	    };
177	
178	    // Navigation stack — back pops; when empty the TUI exits.
179	    let mut stack: Vec<Screen> = vec![initial];
180	
181	    // Commands produced inside match arms, executed after the borrow ends.
182	    enum Cmd {
183	        None,
184	        Break,
185	        Back,
186	        PushSessions(usize),
187	        Cd(String),
188	        ShowSession(String),
189	        ResumeSession(String, String), // (session_id, repo_dir)
190	        Search(String),
191	        NewWorktree(String), // branch name
192	        NewSession(NewSessionConfig),
193	        Redraw,
194	    }
195	
196	    loop {
197	        let (w, h) = terminal::size().unwrap_or((120, 40));
198	        let w = w as usize;
199	        let h = h as usize;
200	
201	        match stack.last().unwrap() {
202	            Screen::Repos { sel } => draw_repos(stdout, repos, *sel, current_repo_dir, w, h, has_cd)?,
203	            Screen::Sessions { repo_idx, sel, sessions, worktrees } => {
204	                draw_sessions(stdout, repos, *repo_idx, sessions, worktrees, *sel, w, h)?
205	            }
206	        }
207	
208	        let cmd = match event::read()? {
209	            Event::Key(k) => match stack.last_mut().unwrap() {
210	                Screen::Repos { sel } => match k.code {
211	                    KeyCode::Char('q') | KeyCode::Esc => Cmd::Break,
212	                    KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
213	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
214	                        terminal::disable_raw_mode().ok();
215	                        std::process::exit(0);
216	                    }
217	                    KeyCode::Up   | KeyCode::Char('k') => { if *sel > 0 { *sel -= 1; } Cmd::None }
218	                    KeyCode::Down | KeyCode::Char('j') => { if *sel + 1 < repos.len() { *sel += 1; } Cmd::None }
219	                    KeyCode::Char('g') => { *sel = 0; Cmd::None }
220	                    KeyCode::Char('G') => { *sel = repos.len().saturating_sub(1); Cmd::None }
221	                    KeyCode::Char(' ') | KeyCode::Right => Cmd::PushSessions(*sel),
222	                    KeyCode::Char('c') if has_cd => Cmd::Cd(repos[*sel].directory.clone()),
223	                    KeyCode::Char('s') => {
224	                        let repo_dir = repos[*sel].directory.clone();
225	                        match new_session_wizard(stdout, &repo_dir, w, h) {
226	                            Some(cfg) => Cmd::NewSession(cfg),
227	                            None => Cmd::Redraw,
228	                        }
229	                    }
230	                    KeyCode::Char('/') => match collect_search_query(stdout, w, h) {
231	                        Some(q) if !q.trim().is_empty() => Cmd::Search(q),
232	                        _ => Cmd::Redraw,
233	                    },
234	                    _ => Cmd::None,
235	                },
236	                Screen::Sessions { sel, sessions, repo_idx, .. } => match k.code {
237	                    KeyCode::Char('q') => Cmd::Break,
238	                    KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
239	                        execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
240	                        terminal::disable_raw_mode().ok();
241	                        std::process::exit(0);
242	                    }
243	                    KeyCode::Esc | KeyCode::Char('h') | KeyCode::Left => Cmd::Back,
244	                    KeyCode::Up   | KeyCode::Char('k') => { if *sel > 0 { *sel -= 1; } Cmd::None }
245	                    KeyCode::Down | KeyCode::Char('j') => { if *sel + 1 < sessions.len() { *sel += 1; } Cmd::None }
246	                    KeyCode::Char('g') => { *sel = 0; Cmd::None }
247	                    KeyCode::Char('G') => { *sel = sessions.len().saturating_sub(1); Cmd::None }
248	                    KeyCode::Char(' ') | KeyCode::Right => {
249	                        if sessions.is_empty() { Cmd::None }
250	                        else { Cmd::ShowSession(sessions[*sel].session_id.clone()) }
251	                    }
252	                    KeyCode::Char('r') => {
253	                        if sessions.is_empty() { Cmd::None }
254	                        else { Cmd::ResumeSession(sessions[*sel].session_id.clone(), repos[*repo_idx].directory.clone()) }
255	                    }
256	                    KeyCode::Char('/') => match collect_search_query(stdout, w, h) {
257	                        Some(q) if !q.trim().is_empty() => Cmd::Search(q),
258	                        _ => Cmd::Redraw,
259	                    },
260	                    KeyCode::Char('n') => match collect_text_input(stdout, "  new worktree branch: ", w, h) {
261	                        Some(b) if !b.trim().is_empty() => Cmd::NewWorktree(b.trim().to_string()),
262	                        _ => Cmd::Redraw,
263	                    },
264	                    KeyCode::Char('s') => {
265	                        let repo_dir = repos[*repo_idx].directory.clone();
266	                        match new_session_wizard(stdout, &repo_dir, w, h) {
267	                            Some(cfg) => Cmd::NewSession(cfg),
268	                            None => Cmd::Redraw,
269	                        }
270	                    }
271	                    _ => Cmd::None,
272	                },
273	            },
274	            Event::Resize(_, _) => Cmd::Redraw,
275	            _ => Cmd::None,
276	        };
277	
278	        match cmd {
279	            Cmd::None => {}
280	            Cmd::Break => break,
281	            Cmd::Back => {
282	                stack.pop();
283	                if stack.is_empty() { break; }
284	            }
285	            Cmd::PushSessions(idx) => {
286	                let sessions = load_sessions(&repos[idx].directory);
287	                let worktrees = fetch_worktrees(&repos[idx].directory);
288	                stack.push(Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees });
289	            }
290	            Cmd::Cd(path) => return Ok(Some(TuiOutcome::CdTo(path))),
291	            Cmd::ResumeSession(id, cwd) => return Ok(Some(TuiOutcome::ResumeSession { id, cwd })),
292	            Cmd::ShowSession(id) => {
293	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
294	                terminal::disable_raw_mode().ok();
295	                let _ = super::show::run(&id);
296	                terminal::enable_raw_mode().ok();
297	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
298	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
299	            }
300	            Cmd::Search(query) => {
301	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
302	                terminal::disable_raw_mode().ok();
303	                let _ = super::search::run(&query, 10, false);
304	                terminal::enable_raw_mode().ok();
305	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
306	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
307	            }
308	            Cmd::NewWorktree(branch) => {
309	                if let Some(Screen::Sessions { repo_idx, worktrees, .. }) = stack.last_mut() {
310	                    let repo_dir = &repos[*repo_idx].directory;
311	                    let notification = create_worktree(repo_dir, &branch);
312	                    // Refresh the worktree list whether or not it succeeded.
313	                    *worktrees = fetch_worktrees(repo_dir);
314	                    // Show the result in the status bar until the next keypress.
315	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
316	                    let msg: String = notification.chars().take(tw as usize).collect();
317	                    let padded = format!("{:<width$}", msg, width = tw as usize);
318	                    execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
319	                    write!(stdout, "\x1b[7m{padded}\x1b[0m").ok();
320	                    stdout.flush().ok();
321	                }
322	            }
323	            Cmd::NewSession(cfg) => {
324	                // Create worktree if requested, then launch the agent.
325	                let launch_dir = if let Some(ref branch) = cfg.branch {
326	                    let _ = create_worktree(&cfg.repo_dir, branch);
327	                    if let Some(Screen::Sessions { repo_idx, worktrees, .. }) = stack.last_mut() {
328	                        *worktrees = fetch_worktrees(&repos[*repo_idx].directory);
329	                    }
330	                    let repo_path = std::path::Path::new(&cfg.repo_dir);
331	                    let parent = repo_path.parent().unwrap_or(repo_path);
332	                    let repo_name = repo_path.file_name()
333	                        .map(|s| s.to_string_lossy().to_string())
334	                        .unwrap_or_else(|| "repo".to_string());
335	                    parent.join(format!("{repo_name}-{}", branch)).to_string_lossy().to_string()
336	                } else {
337	                    cfg.repo_dir.clone()
338	                };
339	
340	                // Copy prompt to clipboard as a convenience.
341	                let prompt = cfg.prompt.trim().to_string();
342	                if !prompt.is_empty() {
343	                    if let Ok(mut child) = std::process::Command::new("pbcopy")
344	                        .stdin(std::process::Stdio::piped())
345	                        .spawn()
346	                    {
347	                        if let Some(stdin) = child.stdin.as_mut() {
348	                            let _ = stdin.write_all(prompt.as_bytes());
349	                        }
350	                        let _ = child.wait();
351	                    }
352	                }
353	
354	                let session_name = cfg.session_name.trim().to_string();
355	                return Ok(Some(TuiOutcome::LaunchAgent {
356	                    cli: cfg.agent_cli,
357	                    cwd: launch_dir,
358	                    session_name,
359	                    prompt,
360	                }));
361	            }
362	            Cmd::Redraw => { execute!(stdout, terminal::Clear(ClearType::All)).ok(); }
363	        }
364	    }
365	
366	    Ok(None)
367	}
