549	fn print_row(stdout: &mut impl Write, line: &str, selected: bool, bg: &str, w: usize, row: u16) -> io::Result<()> {
550	    execute!(stdout, cursor::MoveTo(0, row))?;
551	    if selected {
552	        let colored = with_bg(line, bg);
553	        let vis = visible_width(line);
554	        let pad = w.saturating_sub(vis);
555	        write!(stdout, "\x1b[{bg}m{colored}{}\x1b[0m", " ".repeat(pad))?;
556	    } else {
557	        write!(stdout, "{line}")?;
558	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine))?;
559	    }
560	    Ok(())
561	}
562	
563	fn draw_status(stdout: &mut impl Write, bar: &str, w: usize, h: usize) -> io::Result<()> {
564	    let display: String = bar.chars().take(w).collect();
565	    let padded = format!("{:<width$}", display, width = w);
566	    execute!(stdout, cursor::MoveTo(0, (h - 1) as u16))?;
567	    write!(stdout, "\x1b[7m{padded}\x1b[0m")
568	}
