916	fn create_worktree(repo_dir: &str, branch: &str) -> String {
917	    let repo_path = std::path::Path::new(repo_dir);
918	    let parent = match repo_path.parent() {
919	        Some(p) => p,
920	        None => return "Error: cannot determine repo parent directory".to_string(),
921	    };
922	    let repo_name = repo_path
923	        .file_name()
924	        .map(|s| s.to_string_lossy().to_string())
925	        .unwrap_or_else(|| "repo".to_string());
926	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
927	
928	    // Try -b (new branch) first; fall back to checking out an existing branch.
929	    let out = std::process::Command::new("git")
930	        .args(["worktree", "add", "-b", branch, wt_path.to_str().unwrap_or("")])
931	        .current_dir(repo_dir)
932	        .output();
933	
934	    match out {
935	        Err(e) => format!("Error: {e}"),
936	        Ok(o) if o.status.success() => {
937	            format!("Created worktree: {}", short_path_s(wt_path.to_str().unwrap_or("")))
938	        }
939	        Ok(o) => {
940	            let msg = String::from_utf8_lossy(&o.stderr);
941	            let first = msg.lines().find(|l| !l.trim().is_empty()).unwrap_or("unknown error");
942	            format!("Error: {first}")
