138	pub(crate) fn git_show(repo_dir: &str, path: &str) -> Result<Vec<u8>> {
139	    let out = Command::new("git")
140	        .args(["show", &format!("{}:{}", BRANCH, path)])
141	        .current_dir(repo_dir)
142	        .output()
143	        .context("failed to run git show")?;
144	
145	    if !out.status.success() {
146	        anyhow::bail!("object not found: {}", path);
147	    }
148	    Ok(out.stdout)
149	}
