151	pub(crate) fn checkpoint_remote_url(repo_dir: &str) -> Option<String> {
152	    #[derive(Deserialize)]
153	    struct EntireSettings {
154	        strategy_options: Option<StrategyOptions>,
155	    }
156	    #[derive(Deserialize)]
157	    struct StrategyOptions {
158	        checkpoint_remote: Option<CheckpointRemote>,
159	    }
160	    #[derive(Deserialize)]
161	    struct CheckpointRemote {
162	        repo: String,
163	    }
164	
165	    let settings_path = std::path::Path::new(repo_dir).join(".entire").join("settings.json");
166	    let raw = std::fs::read_to_string(settings_path).ok()?;
167	    let settings: EntireSettings = serde_json::from_str(&raw).ok()?;
168	    let cp_repo = settings.strategy_options?.checkpoint_remote?.repo;
169	
170	    let use_ssh = Command::new("git")
171	        .args(["remote", "get-url", "origin"])
172	        .current_dir(repo_dir)
173	        .output()
174	        .ok()
175	        .and_then(|o| String::from_utf8(o.stdout).ok())
176	        .map(|u| u.trim_start().starts_with("git@") || u.trim_start().starts_with("ssh://"))
177	        .unwrap_or(true);
178	
179	    let url = if use_ssh {
180	        format!("git@github.com:{}.git", cp_repo)
181	    } else {
182	        format!("https://github.com/{}.git", cp_repo)
183	    };
184	
185	    Some(url)
186	}
