use serde::Deserialize;
use std::collections::HashSet;
use std::process::Command;
use uuid::Uuid;

use witchcraft::DB;

use crate::commands::index::{BRANCH, git_show, is_meta_path};

const MIN_CHUNK_CODEPOINTS: usize = 5;
const MAX_CHUNK_CODEPOINTS: usize = 4000;

const CLAUDE_CODE_NAMESPACE: Uuid = Uuid::from_bytes([
    0xa3, 0xf7, 0xc8, 0xd1, 0x6e, 0x2b, 0x4a, 0x91, 0xb5, 0xd0, 0x8f, 0x1e, 0x3c, 0x7a, 0x9b,
    0x2d,
]);

#[derive(Deserialize)]
struct SessionEntry {
    #[serde(rename = "type")]
    entry_type: String,
    timestamp: Option<String>,
    message: Option<Message>,
    #[serde(rename = "gitBranch")]
    git_branch: Option<String>,
    #[serde(rename = "customTitle")]
    custom_title: Option<String>,
    cwd: Option<String>,
}

#[derive(Deserialize)]
struct Message {
    role: Option<String>,
    content: Option<Content>,
}

#[derive(Deserialize)]
#[serde(untagged)]
enum Content {
    Text(String),
    Blocks(Vec<ContentBlock>),
}

#[derive(Deserialize)]
struct ContentBlock {
    #[serde(rename = "type")]
    block_type: String,
    #[serde(default)]

content.content:
50	    #[serde(default)]
51	    text: Option<String>,
52	}
53	
54	struct Chunk {
55	    role: String,
56	    text: String,
57	    timestamp: String,
58	    ts_ms: i64,
59	    byte_offset: u64,
60	    byte_len: u64,
61	    git_branch: Option<String>,
62	}
63	
64	struct SessionInfo {
65	    custom_title: Option<String>,
66	    cwd: Option<String>,
67	}
68	
69	fn codepoint_len(s: &str) -> usize {
70	    s.chars().count()
71	}
72	
73	fn extract_text(content: &Content) -> Option<String> {
74	    match content {
75	        Content::Text(s) => Some(s.clone()),
76	        Content::Blocks(blocks) => {
77	            let texts: Vec<&str> = blocks
78	                .iter()
79	                .filter(|b| b.block_type == "text")
80	                .filter_map(|b| b.text.as_deref())
81	                .collect();
82	            if texts.is_empty() {
83	                None
84	            } else {
85	                Some(texts.join("\n"))
86	            }
87	        }
88	    }
89	}
90	
91	fn sanitize(text: &str) -> String {
92	    let s = strip_system_content(text);
93	    let s = strip_code(&s);
94	    let s = strip_tables(&s);
95	    compact(&s)
96	}
97	
98	fn strip_system_content(text: &str) -> String {
99	    let mut s = text.to_string();
100	    let re_open = Regex::new(r"<([a-z][a-z0-9]*(?:[-:][a-z0-9_]+)+)[\s>]").unwrap();
101	    loop {
102	        let m = match re_open.find(&s) {
103	            Some(m) => m,
104	            None => break,
105	        };
106	        let start = m.start();
107	        let caps = re_open.captures(&s[start..]).unwrap();
108	        let tag_name = caps.get(1).unwrap().as_str().to_string();
109	        let close_tag = format!("</{tag_name}>");
110	        let after_open = match s[start..].find('>') {
111	            Some(i) => start + i + 1,
112	            None => break,
113	        };
114	        let end = match s[after_open..].find(&close_tag) {
